# Create DataFrames
df_maize = pd.DataFrame(maize_data)
df_sorghum = pd.DataFrame(sorghum_data)
df_finger_millet = pd.DataFrame(finger_millet_data)
df_beans = pd.DataFrame(beans_data)
df_irish_potatoes = pd.DataFrame(irish_potatoes_data)
df_sweet_potatoes = pd.DataFrame(sweet_potatoes_data)

# Calculate yields (Production/Area) for each year
for year in [2019, 2020, 2021, 2022, 2023]:
    # Maize yields
    df_maize[f'{year}_Yield'] = np.where(
        df_maize[f'{year}_Area'] > 0,
        df_maize[f'{year}_Production'] / df_maize[f'{year}_Area'],
        0
    )
    
    # Sorghum yields
    df_sorghum[f'{year}_Yield'] = np.where(
        df_sorghum[f'{year}_Area'] > 0,
        df_sorghum[f'{year}_Production'] / df_sorghum[f'{year}_Area'],
        0
    )
    
    # Finger Millet yields
    df_finger_millet[f'{year}_Yield'] = np.where(
        df_finger_millet[f'{year}_Area'] > 0,
        df_finger_millet[f'{year}_Production'] / df_finger_millet[f'{year}_Area'],
        0
    )
    
    # Beans yields
    df_beans[f'{year}_Yield'] = np.where(
        df_beans[f'{year}_Area'] > 0,
        df_beans[f'{year}_Production'] / df_beans[f'{year}_Area'],
        0
    )
    
    # Irish Potatoes yields
    df_irish_potatoes[f'{year}_Yield'] = np.where(
        df_irish_potatoes[f'{year}_Area'] > 0,
        df_irish_potatoes[f'{year}_Production'] / df_irish_potatoes[f'{year}_Area'],
        0
    )
    
    # Sweet Potatoes yields
    df_sweet_potatoes[f'{year}_Yield'] = np.where(
        df_sweet_potatoes[f'{year}_Area'] > 0,
        df_sweet_potatoes[f'{year}_Production'] / df_sweet_potatoes[f'{year}_Area'],
        0
    )

